{
    if (stressGc)
    {
        // As alocações repetidas de strings e arrays temporários que geravam pressão sobre o Garbage Collector foram removidas.
    }

    if (stressCpu)
    {
        for (int k = 0; k < cpuScansPerFrame; k++)
        {
            var allObjects = GameObject.FindObjectsOfType<GameObject>();
            GC.KeepAlive(allObjects);
        }
    }

    if (stressDraw && testPrefab != null)
    {
        int n = Mathf.Max(1, cubesPerFrame);
        for (int i = 0; i < n; i++) SpawnOne();
    }
}",
      "explicacao_didatica": "O Garbage Collector (coletor de lixo, ou GC) é o sistema responsável por liberar automaticamente a memória que o jogo não usa mais. Toda vez que uma string é somada com '+=' ou um novo objeto é criado via 'new' dentro do método Update (que roda a cada quadro), uma nova área de memória é reservada na Heap (memória gerenciada). Quando essa memória enche, o GC é forçado a congelar o jogo para limpar o lixo acumulado. Esse congelamento é o 'gc_collect_ms'. No frame 1009, essa pausa durou 25.84 ms, tempo superior ao limite do jogo inteiro (16.7 ms para 60 FPS), causando uma travada perceptível (stuttering). Ao eliminar a criação desenfreada de objetos temporários no Update, o coletor deixa de ser acionado em momentos críticos."
    }
  ],
